import React, { useContext, useEffect, useState } from "react";
import { Container, Typography, Accordion, AccordionSummary, AccordionDetails, Chip, Box, Button } from "@mui/material";
import ExpandMoreIcon from "@mui/icons-material/ExpandMore";
import changelogData from "../changelog.json";
import { MainContext } from '../Contexts/MainContext';

export default function VersionPage() {
    const [changelog, setChangelog] = useState([]);
    const {
        isVersionPageVisible,
        handleRuleClick
    } = useContext(MainContext);

    useEffect(() => {
        if (changelogData?.changelog) {
            setChangelog(changelogData.changelog);
        } else {
            console.error("Invalid changelog data:", changelogData);
        }
    }, []);

    useEffect(() => {
        console.log("Changelog updated:", changelog);
    }, [changelog]);

    return (
        <Container sx={{
            display: isVersionPageVisible ? 'block' : 'none',
            height: '100%', backgroundColor: 'white', marginTop: 15,
            padding: 0
        }}>
            <Typography variant="h4" gutterBottom>
                {changelogData.metadata?.projectName || "Project"} - Changelog
            </Typography>
            <Typography variant="body2" color="textSecondary" sx={{ mb: 3 }}>
                Dernière mise à jour : {changelogData.metadata?.lastUpdated || "N/A"}
            </Typography>
            <Button onClick={handleRuleClick}> RULES</Button>

            {changelog.length > 0 ? (
                changelog.map((version, index) => (
                    <Accordion key={index}>
                        <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                            <Typography variant="h6">
                                Version {version.version} - {version.releaseDate}
                            </Typography>
                        </AccordionSummary>
                        <AccordionDetails>
                            {version.changes.map((change, idx) => (
                                <Box key={idx} sx={{ mb: 2 }}>
                                    <Chip
                                        label={change.type}
                                        color={change.type === "feature" ? "primary" : "default"}
                                        sx={{ mr: 1 }}
                                    />
                                    <Typography variant="body1">{change.description}</Typography>
                                </Box>
                            ))}
                        </AccordionDetails>
                    </Accordion>
                ))
            ) : (
                <Typography variant="body1" color="textSecondary">
                    Aucun changelog disponible.
                </Typography>
            )}
        </Container>
    );
}
