import { useCallback } from 'react';

/**
 * useCreateCarte
 * Params object must provide the pieces de state et setters nécessaires :
 *  - jsonData, selectedCodex, cartes, setCartes, setAccordionStates,
 *  - setOptionAlerte, t, setFormations, setSelectedCodexVersion,
 *  - setSelectedCodexLogo, setSelectedCodexColor, setSelectedCarteIndex
 */
export default function useCreateCarte({
    jsonData,
    selectedCodex,
    cartes,
    setCartes,
    setAccordionStates,
    setOptionAlerte,
    t,
    setFormations,
    setSelectedCodexVersion,
    setSelectedCodexLogo,
    setSelectedCodexColor,
    setSelectedCarteIndex
}) {
    const handleCreateCarte = useCallback((formation) => {
        let alertMessage = null;

        // Récupère les formations du codex courant
        const formationsFromJson = jsonData.filter((item) => item.codex === selectedCodex);

        // Contrôle 1 : obligation de formation principale
        const hasObligatoryFormation = formationsFromJson[0]?.groupes?.some((groupe) =>
            groupe.formation?.some(f => f.obligatoire === true)
        );

        if (hasObligatoryFormation) {
            const FormObligatoire = cartes.some(opt => opt.obligatoire !== undefined && opt.obligatoire);
            if ((FormObligatoire === false) && (formation.obligatoire === undefined || !formation.obligatoire)) {
                alertMessage = t('alert.select_obligatory_formation');
                setOptionAlerte && setOptionAlerte(<span>{alertMessage}</span>);
                return;
            }
        }

        // Contrôle 2 : formation requise
        if (formation.FormationObligatoire) {
            const sameObligatoireFormation = cartes.filter(carte => carte.FormationObligatoire === formation.FormationObligatoire);
            const obligatoireFormation = cartes.filter(carte => carte.formation === formation.FormationObligatoire);
            if (sameObligatoireFormation.length >= obligatoireFormation.length || cartes === undefined) {
                alertMessage = t('alert.formation_requires_more', { formation: formation.FormationObligatoire });
                setOptionAlerte && setOptionAlerte(<span>{alertMessage}</span>);
                return;
            }
        }

        // Contrôle 3 : Limitation Tag (formation)
        if (formation.LimitationTag) {
            const tableauLettres = formation.LimitationTag.split('');
            const hasMatchingLimitationTag = (carte, lettres) => {
                if (carte.FormationLimitationTag !== undefined) {
                    const tags = Object.keys(carte.FormationLimitationTag[0] || {});
                    return tags.some(tag => lettres.includes(tag));
                }
                return false;
            };
            const cartesAvecFormationLimitationTag = cartes.filter(carte => hasMatchingLimitationTag(carte, tableauLettres));
            const valeursFormationLimitationTag = cartesAvecFormationLimitationTag.map(carte =>
                tableauLettres.map(lettre => carte.FormationLimitationTag[0]?.[lettre]).filter(val => val !== undefined)
            );
            const toutesLesValeursFormation = [].concat(...valeursFormationLimitationTag);
            const sommeDesValeursFormation = toutesLesValeursFormation.reduce((somme, valeur) => somme + valeur, 0);
            const cartesAvecLimitationTag = cartes.filter(carte =>
                carte.LimitationTag && tableauLettres.some(lettre => carte.LimitationTag.includes(lettre))
            );
            const nombreDeFormations = cartesAvecLimitationTag.length;
            if (nombreDeFormations >= sommeDesValeursFormation) {
                alertMessage = t('alert.add_more_main_formations');
                setOptionAlerte && setOptionAlerte(<span>{alertMessage}</span>);
                return;
            }
        }

        // Contrôle 4 : Limitation Tag Option (options limitantes)
        if (formation.LimitationTagOption) {
            const tableauLettres = formation.LimitationTagOption.split('');
            const cartesAvecOptions = cartes.flatMap(carte => carte.options || []);
            const hasMatchingLimitationTag = (opt, lettres) => {
                if (opt.OptionLimitationTag !== undefined) {
                    const tags = Object.keys(opt.OptionLimitationTag[0] || {});
                    return tags.some(tag => lettres.some(lettre => tag.includes(lettre)));
                }
                return false;
            };
            const cartesAvecOptionLimitationTag = cartesAvecOptions.filter(opt => hasMatchingLimitationTag(opt, tableauLettres));
            const valeursOptionLimitationTag = cartesAvecOptionLimitationTag.map(opt => Object.values(opt.OptionLimitationTag[0] || {}));
            const toutesLesValeursOption = [].concat(...valeursOptionLimitationTag);
            const sommeDesValeursOption = toutesLesValeursOption.reduce((somme, valeur) => somme + valeur, 0);
            const cartesAvecLimitationTag = cartes.filter(carte =>
                carte.LimitationTagOption && tableauLettres.some(lettre => carte.LimitationTagOption.includes(lettre))
            );
            const nombreDeFormations = cartesAvecLimitationTag.length;
            if (nombreDeFormations >= sommeDesValeursOption) {
                alertMessage = t('alert.missing_special_option');
                setOptionAlerte && setOptionAlerte(<span>{alertMessage}</span>);
                return;
            }
        }

        // Contrôle 5 : limite de formations similaires
        if (formation.FormationLimite) {
            const selectedFormations = cartes.filter(carte => carte.formation === formation.name);
            if (selectedFormations.length >= formation.FormationLimite) {
                alertMessage = t('alert.max_number_reach');
                setOptionAlerte && setOptionAlerte(<span>{alertMessage}</span>);
                return;
            }
        }

        // Création de la nouvelle carte
        const newCarte = {
            formation: formation.name,
            options: [],
            optionbase: formation.options,
            reference: [],
            rare: formation.rare,
            rarespe: formation.rarespe,
            nbrefoptions: formation.nbrefoptions,
            limiteOptionFormation: formation.limiteOptionFormation,
            obligatoire: formation.obligatoire,
            LimitationTag: formation.LimitationTag,
            FormationLimitationTag: formation.FormationLimitationTag,
            FormationObligatoire: formation.FormationObligatoire,
            LimitationTagOption: formation.LimitationTagOption,
            GrpPrincipal: formation.GrpPrincipal
        };

        // mise à jour des états
        setAccordionStates(prev => [...prev, true]);
        const updatedCartes = [...(cartes || []), newCarte];
        setCartes(updatedCartes);
        setSelectedCarteIndex && setSelectedCarteIndex(updatedCartes.length - 1);

        // retourne nouvel objet si besoin
        return newCarte;
    }, [
        jsonData,
        selectedCodex,
        cartes,
        setCartes,
        setAccordionStates,
        setOptionAlerte,
        t,
        setSelectedCarteIndex
    ]);

    return { handleCreateCarte };
}